TLM.f("Tempora/Quad2-2",{"officium":"Feria Tertia infra Hebdomadam II in Quadragesima","rule":["no Gloria","Suffragium=Sanctorum;Vivis;;","Super popul"],"ruleInherited":["no Gloria","Credo","Prefatio=Quad","Suffragium=Sanctorum;Vivis;;"],"fallback":"Tempora/Quad2-0","sections":{"Introitus":[{"k":"ref","la":"Ps 26:8; 26:9"},{"k":"text","la":"Tibi dixit cor meum, quæsívi vultum tuum. vultum tuum, Dómine, requíram: ne avértas fáciem tuam a me."},{"k":"ref","la":"Ps 26:1"},{"k":"text","la":"Dóminus illuminátio mea, et salus mea: quem timébo?"},{"k":"macro","name":"Gloria"},{"k":"text","la":"Tibi dixit cor meum, quæsívi vultum tuum. vultum tuum, Dómine, requíram: ne avértas fáciem tuam a me."}],"Oratio":[{"k":"text","la":"Pérfice, quǽsumus, Dómine, benígnus in nobis observántiæ sanctæ subsídium: ut, quæ te auctóre faciénda cognóvimus, te operánte impleámus."},{"k":"macro","name":"Per Dominum"}],"Lectio":[{"k":"text","la":"Léctio libri Regum."},{"k":"ref","la":"3 Reg 17:8-16"},{"k":"text","la":"In diébus illis: Factus est sermo Dómini ad Elíam Thesbíten, dicens: Surge et vade in Saréphta Sidoniórum, et manébis ibi: præcépi enim ibi mulíeri víduæ, ut pascat te. Surréxit et ábiit in Saréphta. Cumque venísset ad portam civitátis, appáruit ei múlier vídua cólligens ligna, et vocávit eam, dixítque ei: Da mihi páululum aquæ in vase, ut bibam. Cumque illa pérgeret, ut afférret, clamávit post tergum ejus, dicens: Affer mihi, óbsecro, et buccéllam panis in manu tua. Quæ respóndit: Vivit Dóminus, Deus tuus, quia non hábeo panem, nisi quantum pugíllus cápere potest farínæ in hýdria, et páululum ólei in lécytho: en, cóllige duo ligna, ut ingrédiar, et fáciam illum mihi et fílio meo, ut comedámus et moriámur. Ad quam Elías ait: Noli timére, sed vade, et fac, sicut dixísti: verúmtamen mihi primum fac de ipsa farínula subcinerícium panem párvulum, et affer ad me: tibi autem et fílio tuo fácies póstea. Hæc autem dicit Dóminus, Deus Israël: Hýdria farínæ non defíciet, nec lécythus ólei minuétur, usque ad diem, in qua Dóminus datúrus est plúviam super fáciem terræ. Quæ ábiit, et fecit juxta verbum Elíæ: et comédit ipse et illa et domus ejus: et ex illa die hýdria farínæ non defécit, et lécythus ólei non est imminútus, juxta verbum Dómini, quod locútus fúerat in manu Elíæ."}],"Graduale":[{"k":"ref","la":"Ps 54:23; 54:17; 54:18; 54:19"},{"k":"text","la":"Jacta cogitátum tuum in Dómino, et ipse te enútriet."},{"k":"text","la":"Dum clamárem ad Dóminum, exaudívit vocem meam ab his, qui appropínquant mihi.","mark":"V"}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum."},{"k":"ref","la":"Matt 23:1-12"},{"k":"text","la":"In illo témpore: Locútus est Jesus ad turbas et ad discípulos suos, dicens: Super cáthedram Móysi sedérunt scribæ et pharisǽi. Omnia ergo, quæcúmque díxerint vobis, serváte et fácite: secúndum ópera vero eórum nolíte fácere: dicunt enim, et non fáciunt. Alligant enim ónera grávia et importabília, et impónunt in húmeros hóminum: dígito autem suo nolunt ea movére. Omnia vero ópera sua fáciunt, ut videántur ab homínibus: dilátant enim phylactéria sua, et magníficant fímbrias. Amant autem primos recúbitus in cenis, et primas cáthedras in synagógis, et salutatiónes in foro, et vocári ab homínibus Rabbi. Vos autem nolíte vocári Rabbi: unus est enim Magíster vester, omnes autem vos fratres estis. Et patrem nolíte vocáre vobis super terram, unus est enim Pater vester, qui in cœlis est. Nec vocémini magístri: quia Magíster vester unus est, Christus. Qui major est vestrum, erit miníster vester. Qui autem se exaltáverit, humiliábitur: et qui se humiliáverit, exaltábitur."}],"Offertorium":[{"k":"ref","la":"Ps 50:3"},{"k":"text","la":"Miserére mei, Dómine, secúndum magnam misericórdiam tuam: dele, Dómine, iniquitátem meam."}],"Secreta":[{"k":"text","la":"Sanctificatiónem tuam nobis, Dómine, his mystériis operáre placátus: quæ nos et a terrénis purget vítiis, et ad cœléstia dona perdúcat."},{"k":"macro","name":"Per Dominum"}],"Communio":[{"k":"ref","la":"Ps 9:2-3"},{"k":"text","la":"Narrábo ómnia mirabília tua: lætábor, et exsultábo in te: psallam nómini tuo, Altíssime."}],"Postcommunio":[{"k":"text","la":"Ut sacris, Dómine, reddámur digni munéribus: fac nos tuis, quǽsumus, semper obœdíre mandátis."},{"k":"macro","name":"Per Dominum"}],"Super populum":[{"k":"rubric","la":"Oratio super populum"},{"k":"text","la":"Orémus."},{"k":"text","la":"Humiliáte cápita vestra Deo."},{"k":"text","la":"Propitiáre, Dómine, supplicatiónibus nostris, et animárum nostrárum medére languóribus: ut, remissióne percépta, in tua semper benedictióne lætámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"2e0190f6961c911f":{"t":"Ps 26, 8 i 9, Ps 26, 1\n(Ps 26, 8 i 9) Tebi govori moje srce; tražim lice tvoje, Gospodine, tvoje lice tražim. Ne skrivaj lica svojega od mene. (Ps 26, 1) Gospodin mi je svjetlo i spas. Koga da se bojim?\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 26, 8 i 9) Tebi govori moje srce; tražim lice tvoje, Gospodine, tvoje lice tražim. Ne skrivaj lica svojega od mene.","kn":"(Ps. 26, 8, 9). Tebi govori srce moje, tebe traži lice moje, lice Tvoje, Gospodine, tražim, ne odvrati od mene lica svojega! (Ps. 26, 1). Gospodin je svjetlost moja i spasenje moje, koga da se bojim? Slava Ocu . . . Tebi govori . . .","knRef":"Kniewald 1942, str. 134–135 (snimka 68) (OCR)"},"47e9d76f1ce44e8d":{"t":"<i>Pomolimo se</i>.\nUsavrši, molimo, Gospodine, u nama dobrostivo svoju pomoć u svetom obdržavanju korizme, da tvojim sudjelovanjem izvršimo što smo po tebi upoznali da nam valja činiti.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Molimo, Gospodine, usavrši u nama blagostivo svoju pomoć, te ustrajući u svetom postu, Tvojom okreipom Izvršimo ono, što smo po Tebi spoznali da nam valja činiti, po G. n.","knRef":"Kniewald 1942, str. 134–135 (snimka 68) (OCR)"},"2ea4067ea9c3d9af":{"t":"1* Kr 17, 8-16\nČitanje knjige Kraljeva. U one dane Gospodin zapovjedi Iliji Tezbićaninu: Ustani i pođi u Sareptu kod Sidona. Ostani ondje, jer sam zapovjedio nekoj udovici da te hrani. I on se uputi u Sareptu. Kad je stigao na gradska vrata, vidi ženu gdje kupi drva. Pozva je i zamoli: Daj mi u posudici malo vode da se napijem. Kad je pošla da donese, poviče za njom: Molim te, donesi mi u svojoj ruci i komadić kruha. Ona odgovori: Tako bio živ Gospodin Bog tvoj, nemam kuha nego šačicu brašna u zdjeli i kapljicu ulja u staklenki, i sada skupljam malo drva da pođem i ispečem sebi i svojem sinu te pojedemo i umremo. Ilija joj navijesti: Ne boj se! Pođi i ispeci kao što si rekla. Ali prije pod crijepnjom ispeci meni od toga brašna mali kruh i donesi mi. Sebi i sinu ispeći ćeš kasnije. Ovo govori Gospodin Bog Izraelov: Brašna u zdjeli neće ponestati, niti će biti manje ulja u staklenki do dana kada će Gospodin dati zemlji kišu. Ona otiđe, učini kao što joj je kazao Ilija. Jeo je on i ona i svi njezini domaći. I od onoga dana nije ponestalo brašna u zdjeli niti je bilo manje ulja u staklenki kako je Gospodin obećao preko Ilije. [* Vulgata Sixto-Clementina sadrži četiri knjige o kraljevima, od kojih se prve dvije u drugim novijim izdanjima označavaju kao knjige o Samuelu: I Reg, II Reg, III Reg, IV Reg odgovaraju 1 Sam, 2 Sam, 1 Kr, 2 Kr]","kn":"Čitanje knjige Kraljeva (III. Kr. 17, 8-16). U one dane: Dođe riječ Gospodnja Iliji Tezbićaninu govoreći: Ustani i pođi u Sareptu Sidonsku, i ostani ondje: jer ondje zapoivjedih ženi udovici, da te hrani. I ustavši otide u Sareptu. A kad . dođe na vrata gradska, pojavi se žena udovica kupeči drva, a on je pozove, i reče joj: Daj mi malo vode u sudu, da se napijem. A kad ona iđaše, da donese, poviče za njom govoreći: Donesi mi, moUm te, i komadić kruha u ruci svojoj. A ona odgovori: Tako Živ bio Gospodin Bog tvoj, nemam kruha do šaku brašna u zdjeli, i kapljice ulja u staklenici, i evo kupim malo drva, da otidem i zgotovim sebi i sinu svojemu, da pojedemo i umremo. A Ilija joj reče: Ne boj se, nego idi i zgotovi, kako si rekla; ali zgotovi prije meni od to malo brašna hljebac imd pepelom, i donesi mi: a sebi i sinu svojemu zgotovit ćeš poslije. A ovo govori Gospodin Bog Izraelov: Brašna u zdjeli ne će ponestati, niti će ulje u staklenici doći na manje do dana, kad Gospodin dadne dažd zemlji. A ona otide, 1 učini kako reče Ilija, i blagova on i ona i domaći njezini: i od onog dana ne ponesta brašna u zdjeli, niti ulje u staklenici dođe na manje, po riječi Gospodnjoj, koju reče preko Ilije.","knRef":"Kniewald 1942, str. 134–135 (snimka 68) (OCR)"},"66177f8c11745c60":{"t":"Ps 54, 23 i 17 i 18 i 19\nPrebaci na Gospodina svoju brigu i on će te hraniti. Kad sam zazvao Gospodina, uslišio je moj glas protiv onih koji mi se neprijateljski približuju.","kn":"(Ps. 54, 23, 17, 18, 19). Prepusti Gospodinu brige s.voje i on će te uzdržati. Kad sam vapio Gospodinu, uslišao je glas moj od onih, koji mi se približavahu.","knRef":"Kniewald 1942, str. 134–135 (snimka 68) (OCR)"},"4a81a47f3a5e539d":{"t":"Mt 23, 1-12\nSlijedi sveto Evanđelje po Mateju. U ono vrijeme Isus je govorio narodu i svojim učenicima: Na Mojsijevu učiteljsku katedru zasjeli su književnici i farizeji. Sve što vam reknu držite i činite, ali nemojte se ravnati po njihovim djelima, jer oni govore, a ne vrše. Vežu teška i nepodnošiva bremena i postavljaju ih ljudima na leda, ali ih sami neće ni taknuti svojim prstom. Sva svoja djela čine zato da ih vide ljudi. Šire svoje zapise, produljuju svoje rese. Vole prva mjesta na gozbama i prva sjedala u zbornicama, pozdrave na trgovima i da ih ljudi nazivaju: Učitelju. Vi se nemojte zvati učiteljima! Jedan je vaš Učitelj, a vi ste svi braća. Nikoga na zemlji ne zovite ocem, jer imate samo jednoga Oca na nebu. Ne dopustite, da vas nazivaju vođama, jer imate samo jednoga Vođu Krista. Tko je među vama najveći, neka vam bude sluga! Tko se uzvisi, bit će ponižen, a tko se ponizi bit će uzvišen.","kn":"t Slijedi sv. evanđelje po Mateju (23, 1-12). U ono vrijeme reče Isus narodu i svojim učenicima: Na Mojsijevu stolicu sjedoše književnici i farizeji. Sve dakle, štO' vam kažu, držite 1 činite, ali po njihovim djelima nemojte činiti, jer govore, a ne čine. Vežu teška i nesnosna bremena i tovare na pleća ljudska, a prstom svojim ne će da ih maknu. Sva svoja djela čine, da ih ljudi vide, jer rašlruju svoje zapise i prave velike rese na haljinama svojim. Najvole začelje na gozbama i prva mjesta po zbornicama, i da ih pozdravljaju na trgovima i da Ih ljudi zovu »rabi«. Ali vi se ne zovite »rabi«, jer je jedan vaš učitelj, a vi ste svi braća. I ocem svojim ne zovite nikoga na zemlji, jer je jedan otac vaš nebeski. Niti se zovite vođe, .jer je jedan vaš vođa; Krist. Najveći između vas, meka vam bude sluga, A koji sebe uzvisuje, ponizit će se, i koji sebe ponizuje, uzvisit će se.","knRef":"Kniewald 1942, str. 134–135 (snimka 68) (OCR)"},"bffbdcf2d0520142":{"t":"Ps 50, 3\nSmiluj mi se Gospodine, po velikom milosrđu svome. Gospodine, uništi krivicu moju.","kn":"(Ps. 50, 3). Smiluj mi se. Bože, po velikom milosrđu svojem i uništi, Gospodine, krivicu moju!","knRef":"Kniewald 1942, str. 136–137 (snimka 69) (OCR)"},"20f3a2d8299f0718":{"t":"Ublažen ovim tajnama izvrši, Gospodine, na nama svoje posvećenje, koje će nas očistiti od zemaljskih mana i dovesti do nebeskih darova.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Posveti nas, Gospodine, pomiren ovim otajstvima, očisti od zemaljskih mana i dovedi k nebeskim darovima, po G. n.","knRef":"Kniewald 1942, str. 136–137 (snimka 69) (OCR)"},"8e0447f4695d07e4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi Gospodine, sveti Oče, svemogući vječni Bože: – ti tjelesnim postom suzbijaš opačine, uzdižeš dušu, daješ krepost i nagrade po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo 1 spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože. koji tjelesnim postom obuzdavaš opačine, duh dižeš, daješ krepost i nagrade,' po Kristu, Gospodinu našemu; po kojem veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti, Nebesa Te 1 nebeske Red i čin sv. mise moći i blaženi Serafini zadružnim klicanjem zajedno slave. Zapovjedi, molimo, da se s njima smiju sjediniti i naši glasovi, koji govore u smjernom ispovijedanju:","knRef":"Kniewald 1942, str. 20–21 (snimka 11) (OCR)"},"dcec05d16fd456c3":{"t":"Ps 9, 2-3\nripovijedat ću sva čudesa tvoja, radovat ću se i kliktati u tebi, pjevat ću psalme imenu tvojemu, Svevišnji.","kn":"(Ps. 9, 2, 3). Pripovijedat ću sva divna djela Tvoja, radiovat ću se i klicat ću u Tebi, psalme ću pjevati imenu Tvojemu, Višnji,","knRef":"Kniewald 1942, str. 362–363 (snimka 182) (OCR)"},"95317bb80f80e17b":{"t":"<i>Pomolimo se</i>.\nDa budemo, Gospodine, dostojni svetih darova, daj, molimo, da uvijek budemo poslušni tvojim zapovijedima.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Daj, molimo Te, Gospodine, da budemo uvijek poslušni Tvojim zapovijedima, te postanemo dostojnima Tvojih svetih darova, po G. n.","knRef":"Kniewald 1942, str. 136–137 (snimka 69) (OCR)"},"c4327b1b0bb181cf":{"t":"<i>Pomolimo se</i>.\n<i>Prignite pred Bogom svoje glave</i>.\nMilostiv budi, Gospodine, našim prošnjama i izliječi bolesti naših duša, da se primivši oproštenje uvijek radujemo zbog tvoga blagoslova.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pomolimo se! Prignite ponizno glave svoje pred Bogom! Cuj, Gospodine, naše prošnje i izliječi bolesti duša naših, da primimo oproštenje i da se uvijek radujemo u Tvojem blagoslovu, po G. n.","knRef":"Kniewald 1942, str. 136–137 (snimka 69) (OCR)"}}});
